parameters.jsCode:
const body = $json.body || $json;

// 1. Identifiant unique de la candidature
const applicationId = body.applicationId || `app-${Date.now()}`;

// 2. Canal de diffusion cible ('whatsapp' | 'email')
const rawChannel = (body.channel || 'whatsapp').toLowerCase().trim();
const channel = rawChannel === 'email' ? 'email' : 'whatsapp';

// 3. Extraction & normalisation des données étudiant
const student = body.student || {};
const studentFullName = student.fullName || student.name || 'Dave Lionel KAMENI';
const studentEmail = student.email || 'etudiant@campus360.app';
const rawStudentPhone = (student.phoneWhatsapp || student.phone || '237672364124').replace(/[^0-9]/g, '');
const studentPhone = rawStudentPhone.startsWith('6') && rawStudentPhone.length === 9 ? `237${rawStudentPhone}` : rawStudentPhone;
const instanceName = student.instanceName || `student-${studentPhone}`;
const studentMajor = student.major || 'Génie Logiciel / Informatique';
const studentUniversity = student.university || 'Université / École Partenaire';

// 4. Extraction & normalisation des données recruteur / offre
const job = body.job || {};
const jobTitle = job.title || 'Stagiaire Développeur';
const companyName = job.companyName || job.company || 'Entreprise Partenaire';
const jobLocation = job.location || 'Douala / Yaoundé';
const rawRecruiterPhone = (job.recruiterWhatsapp || job.phone || '237670009988').replace(/[^0-9]/g, '');
const recruiterPhone = rawRecruiterPhone.startsWith('6') && rawRecruiterPhone.length === 9 ? `237${rawRecruiterPhone}` : rawRecruiterPhone;
const recruiterEmail = job.recruiterEmail || job.email || 'recrutement@entreprise.com';

// 5. Extraction du dossier de candidature
const dossier = body.dossier || {};
const cvPdfUrl = dossier.cvPdfUrl || body.cvPdfUrl || 'https://zlzwoqqnkvxndmtnzdsm.supabase.co/storage/v1/object/public/cvs/cv-sample.pdf';
const letterText = dossier.letterText || body.letterText || 'Madame, Monsieur,\n\nVivement intéressé par votre entreprise, je vous soumets ma candidature pour ce stage.';

// Construction du pitch WhatsApp officiel
const defaultPitch = `📢 *Nouvelle Candidature — Campus 360*\n\nBonjour *${companyName}*,\n\nJe suis *${studentFullName}*, étudiant en *${studentMajor}* (${studentUniversity}).\n\nJ\'ai l\'honneur de postuler à votre offre de stage : *${jobTitle}* à *${jobLocation}*.\n\n📄 Mon CV officiel 2 colonnes est joint directement à ce message (document PDF ci-dessus).\n\n💬 *Présentation du profil :*\n${letterText.slice(0, 320)}${letterText.length > 320 ? '...' : ''}\n\n📞 *WhatsApp Direct :* https://wa.me/${studentPhone}\n✉️ *Email Candidat :* ${studentEmail}\n🆔 *Réf. Candidature :* ${applicationId}\n\nBien cordialement,\n*${studentFullName}* (Postulé via Campus 360)`;
const whatsappPitch = dossier.whatsappPitch || body.whatsappPitch || defaultPitch;

// 6. Calcul du Jitter Anti-Ban aléatoire (15 à 30 secondes pour envois groupés)
const jitterSeconds = Math.floor(Math.random() * 16) + 15;

// 7. Formatage de l'email SMTP professionnel HTML
const emailSubject = `Candidature Stage : ${jobTitle} — ${studentFullName}`;
const emailHtml = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Candidature Campus 360</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #f8fafc; color: #1e293b; margin: 0; padding: 24px; line-height: 1.6; }
    .wrapper { max-width: 620px; margin: 0 auto; background: #ffffff; border-radius: 12px; border: 1px solid #e2e8f0; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05); }
    .header { background: #0f172a; color: #ffffff; padding: 28px 24px; text-align: center; }
    .badge { display: inline-block; background: #2563eb; color: #ffffff; padding: 4px 14px; border-radius: 9999px; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 10px; }
    .title { margin: 0; font-size: 20px; font-weight: 700; color: #ffffff; }
    .subtitle { margin: 6px 0 0 0; font-size: 14px; color: #94a3b8; }
    .content { padding: 28px 24px; }
    .info-card { background: #f1f5f9; border-radius: 8px; padding: 18px; margin: 18px 0; border-left: 4px solid #2563eb; }
    .info-card p { margin: 6px 0; font-size: 14px; }
    .motivation-box { background: #f8fafc; border-radius: 8px; padding: 16px; border: 1px dashed #cbd5e1; font-style: italic; color: #334155; margin: 16px 0; white-space: pre-line; }
    .cta-container { text-align: center; margin: 28px 0; }
    .cta-btn { display: inline-block; background: #2563eb; color: #ffffff !important; text-decoration: none; padding: 14px 28px; border-radius: 8px; font-weight: 600; font-size: 15px; }
    .footer { padding: 20px 24px; background: #f8fafc; border-top: 1px solid #e2e8f0; font-size: 12px; color: #64748b; text-align: center; line-height: 1.5; }
  </style>
</head>
<body>
  <div class="wrapper">
    <div class="header">
      <div class="badge">Campus 360 • Candidature Certifiée</div>
      <h1 class="title">Nouvelle Candidature Reçue</h1>
      <p class="subtitle">${jobTitle} chez ${companyName}</p>
    </div>
    <div class="content">
      <p>Bonjour l'équipe Recrutement de <strong>${companyName}</strong>,</p>
      <p>Un candidat qualifié de la plateforme <strong>Campus 360</strong> vient de postuler à votre offre de stage.</p>
      <div class="info-card">
        <p><strong>👤 Candidat :</strong> ${studentFullName}</p>
        <p><strong>🎓 Formation :</strong> ${studentMajor} (${studentUniversity})</p>
        <p><strong>📞 WhatsApp :</strong> +${studentPhone}</p>
        <p><strong>✉️ Email :</strong> ${studentEmail}</p>
        <p><strong>📍 Localisation :</strong> ${jobLocation}</p>
      </div>
      <h3 style="margin-top: 24px; font-size: 15px; color: #0f172a;">Lettre de motivation & accroche :</h3>
      <div class="motivation-box">${letterText}</div>
      <div class="cta-container">
        <a href="${cvPdfUrl}" class="cta-btn" target="_blank">📄 Consulter le CV Officiel (PDF)</a>
      </div>
      <p style="font-size: 13px; color: #64748b; margin-top: 20px;">
        💡 <strong>Réponse directe :</strong> Vous pouvez répondre directement à cet email. L\'en-tête <em>Reply-To</em> est configuré pour joindre <strong>${studentEmail}</strong>.
      </p>
    </div>
    <div class="footer">
      Campus 360 — Plateforme d\'insertion professionnelle étudiante en Afrique.<br>
      Identifiant dossier : <code>${applicationId}</code>
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    applicationId,
    channel,
    jitterSeconds,
    student: {
      fullName: studentFullName,
      phoneWhatsapp: studentPhone,
      email: studentEmail,
      major: studentMajor,
      university: studentUniversity,
      instanceName
    },
    job: {
      title: jobTitle,
      companyName,
      location: jobLocation,
      recruiterWhatsapp: recruiterPhone,
      recruiterEmail
    },
    dossier: {
      cvPdfUrl,
      letterText,
      whatsappPitch
    },
    emailSubject,
    emailHtml,
    dispatchedAt: new Date().toISOString()
  }
}];

parameters.jsonBody:
={{ JSON.stringify({
  number: $json.job.recruiterWhatsapp,
  mediatype: 'document',
  mimetype: 'application/pdf',
  media: $json.dossier.cvPdfUrl,
  fileName: 'CV_Officiel.pdf',
  caption: $json.dossier.whatsappPitch
}) }}

={{ JSON.stringify({
  from: 'Campus 360 <onboarding@resend.dev>',
  to: [$json.job.recruiterEmail],
  reply_to: $json.student.email,
  subject: $json.emailSubject,
  html: $json.emailHtml
}) }}

={{ JSON.stringify({
  status: 'DELIVERED',
  dispatch_status: 'DELIVERED',
  delivered_at: new Date().toISOString()
}) }}

parameters.responseBody:
={{ JSON.stringify({
  success: true,
  message: 'Candidature expédiée avec succès au recruteur',
  applicationId: $('Validation Payload & Jitter Anti-Ban').item.json.applicationId,
  channel: $('Validation Payload & Jitter Anti-Ban').item.json.channel,
  status: 'DELIVERED',
  recruiterTarget: $('Validation Payload & Jitter Anti-Ban').item.json.channel === 'whatsapp' ? $('Validation Payload & Jitter Anti-Ban').item.json.job.recruiterWhatsapp : $('Validation Payload & Jitter Anti-Ban').item.json.job.recruiterEmail,
  deliveredAt: new Date().toISOString()
}) }}
